// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;

import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbNativeTimedExplainTest {

	@TempDir
	File dataDir;

	@Test
	void compiledPlanExposesMeasuredQueryPullTimeWithoutFabricatingOperatorTimes() {
		var repository = new SailRepository(new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc").setForceSync(false).setNativeEvaluationEnabled(true)));
		repository.init();
		try (var connection = repository.getConnection()) {
			var vf = repository.getValueFactory();
			var left = vf.createIRI("urn:test:left");
			var right = vf.createIRI("urn:test:right");
			connection.begin();
			for (int i = 0; i < 64; i++) {
				var subject = vf.createIRI("urn:test:subject:" + i);
				connection.add(subject, left, vf.createLiteral(i));
				connection.add(subject, right, vf.createLiteral(-i));
			}
			connection.commit();

			String sparql = """
					SELECT ?s ?v WHERE {
						{ ?s <urn:test:left> ?v }
						UNION
						{ ?s <urn:test:right> ?v }
					}
					""";
			var explanation = connection.prepareTupleQuery(sparql).explain(Explanation.Level.Timed);
			var plan = explanation.toGenericPlanNode();
			assertThat(plan.getStringMetricActual("nativeExecutionPath")).isNotBlank();
			assertThat(explanation.tupleExpr()).isInstanceOfSatisfying(QueryRoot.class, root -> {
				assertThat(root.getResultSizeActual()).isEqualTo(128);
				assertThat(root.getTotalTimeNanosActual()).isPositive();
				assertThat(plan.getQueryPullTimeActual()).isEqualTo(root.getTotalTimeNanosActual() / 1_000_000.0);
			});
			assertThat(plan.getTotalTimeActual()).isNull();
			assertThat(plan.getSelfTimeActual()).isNull();

			for (var level : Explanation.Level.values()) {
				if (level != Explanation.Level.Timed) {
					var other = connection.prepareTupleQuery(sparql).explain(level);
					assertThat(other.toJson()).as(level.name()).doesNotContain("queryPullTimeActual");
				}
			}
		} finally {
			repository.shutDown();
		}
	}
}
